def zone_shape_hint(profile_key, entity, kind, parent, zone_id,
        half_fractions=None):
    key = None
    try:
        key = (str(profile_key[0]), str(profile_key[1]), str(zone_id))
    except Exception:
        key = None
    if key is not None and key in PROFILE_ZONE_SHAPE_OVERRIDES:
        return str(PROFILE_ZONE_SHAPE_OVERRIDES[key])
    if str(kind or '').lower() == 'crew':
        return 'crew_capsule_head'
    zone_id = str(zone_id or '')
    if zone_id in _MODULE_ZONE_SHAPES:
        return _MODULE_ZONE_SHAPES[zone_id]
    return _ENTITY_DEFAULT_SHAPES.get(str(entity or ''), 'box')
